export function translate(key, lang = 'en', vars = {}) {
  const editionVars = {
    maxImages: EDITION.maxImages,
    maxInputSize: formatEditionBytes(EDITION.maxInputBytes, lang),
    maxOutputSize: formatEditionBytes(EDITION.maxBatchOutputBytes, lang)
  };
  const template = messages[lang]?.[key] ?? messages.en[key] ?? key;
  return template.replace(/\{(\w+)\}/g, (_, name) => vars[name] ?? editionVars[name] ?? `{${name}}`);
}
